(() => {
  'use strict';
  const $=s=>document.querySelector(s), catalog=window.CHANCE2_CATALOG.products, pricing=window.CHANCE2_PRICING;
  const api=(window.CHANCE2_STORE?.apiOrigin||'').replace(/\/$/,'');
  const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
  function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{}}
  const category=p=>/chairmat|chair mat|caster|footrest|floor protect|desk component|desk pad/i.test(p.name)?'Accessories':/chair|stool|sofa|seating|recliner/i.test(p.name)?'Chairs & seating':/bookcase|shelv|cabinet|locker|storage/i.test(p.name)?'Storage & shelving':/desk|workstation/i.test(p.name)?'Desks':/\btables?\b/i.test(p.name)?'Tables':'Accessories';
  const cents=p=>{const shipping=pricing.supplierShippingBySku[p.sku]??pricing.defaultSupplierShipping;return p.supplierPrice==null||shipping==null?null:Math.round((p.supplierPrice+shipping)*pricing.multiplier*100);};
  const byUrl=new Map(catalog.map(p=>[p.url,p]));
  let bag=read('chance2.bag',[]).filter(x=>byUrl.has(x.url)&&Number.isSafeInteger(x.quantity)&&x.quantity>0);
  let cardCode=read('chance2.card',null),card=null,page=1,config=null,toastTimer,detailUrl;
  async function request(path,{method='GET',body,code=cardCode}={}){const response=await fetch(api+path,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(code?{'X-Card-Code':code}:{})},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw Error('The shop connection is not available yet. Please try again later.');}if(!response.ok)throw Error(data.error||'The shop connection is not available.');return data;}
  function toast(message){$('#toast').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',3500);}
  function bagChanged(){save('chance2.bag',bag);$('#bag-count').textContent=bag.reduce((s,p)=>s+p.quantity,0);renderCart();}
  function add(url){const item=bag.find(x=>x.url===url);if(item)item.quantity++;else bag.push({url,quantity:1});bagChanged();toast('A little more fancy, added to your bag.');}
  function render(){let list=catalog.filter(p=>(p.name+' '+p.sku).toLowerCase().includes($('#search').value.toLowerCase())&&($('#category').value==='All furniture'||category(p)===$('#category').value));const sort=$('#sort').value;
    if(sort==='low')list.sort((a,b)=>(cents(a)??Infinity)-(cents(b)??Infinity));
    if(sort==='high')list.sort((a,b)=>(cents(b)??-1)-(cents(a)??-1));
    if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));
    if(sort==='featured')list.sort((a,b)=>Number(category(a)==='Accessories')-Number(category(b)==='Accessories'));
    const pages=Math.max(1,Math.ceil(list.length/12));page=Math.min(page,pages);
    $('#count').textContent=list.length.toLocaleString()+' pieces to explore';
    $('#filter-summary').textContent=$('#category').value==='All furniture'?'All furniture & accessories':$('#category').value;
    $('#products').innerHTML=list.slice((page-1)*12,page*12).map(p=>`<article class="product"><button class="product-image" data-detail="${esc(p.url)}" aria-label="View ${esc(p.name)}"><img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy" width="200" height="200"></button><div class="product-info"><small>${esc(category(p))}</small><button class="product-title" data-detail="${esc(p.url)}"><h3>${esc(p.name)}</h3></button><div class="product-bottom"><span class="price ${cents(p)==null?'quote':''}">${cents(p)==null?'Price on request':money(cents(p))}</span>${cents(p)==null?`<button class="quote-button" data-detail="${esc(p.url)}">View details ↗</button>`:`<button class="add-button" data-add="${esc(p.url)}" aria-label="Add ${esc(p.name)} to bag">+</button>`}</div></div></article>`).join('')||'<p class="empty">Nothing here just yet. Try another word or category.</p>';
    $('#page').textContent=`${page} / ${pages}`;$('#prev').disabled=page===1;$('#next').disabled=page===pages;
  }
  function detail(url){detailUrl=url;const p=byUrl.get(url);$('#detail-content').innerHTML=`<div class="detail-layout"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><p class="eyebrow">${esc(category(p))} · ${esc(p.sku)}</p><h2 id="detail-title">${esc(p.name)}</h2><div class="price">${cents(p)==null?'Price on request':money(cents(p))}</div><p>${cents(p)==null?'We’re confirming the supplier’s delivery cost for this piece before offering a final price.':'Your next favorite is ready for your bag. Delivery and any applicable taxes are shown at checkout.'}</p>${cents(p)==null?'':`<button class="button primary full" id="detail-add">Add to your bag +</button>`}<p class="detail-reward">Five paid orders earn 25% off your next merchandise order.</p></div></div>`;$('#detail').showModal();$('#detail-add')?.addEventListener('click',()=>add(detailUrl));}
  function renderCard(){const punches=card?.punches||0;$('#punches').innerHTML=Array.from({length:5},(_,i)=>`<span class="punch ${i<punches?'filled':''}" aria-label="${i+1}${i<punches?', punched':', unpunched'}">${i<punches?'✓':i+1}</span>`).join('');$('#punches').setAttribute('aria-label',`${punches} of 5 punches`);$('#reward-status').textContent=card?.rewardReserved?'Your 25% reward is waiting in your pending checkout.':punches===5?'25% unlocked. Your next merchandise order is on the card.':`${punches} of 5 punches. ${5-punches} paid order${5-punches===1?'':'s'} to your reward.`;$('#open-card').hidden=Boolean(card);$('#copy-card').hidden=!card;$('#card-code').textContent=card?'Your card code: '+card.id:'';renderCart();}
  async function ensureCard(){if(card)return card;if(cardCode){card=await request('/api/card');}else{card=await request('/api/cards',{method:'POST'});cardCode=card.id;save('chance2.card',cardCode);}renderCard();return card;}
  function renderCart(){const items=bag.map(x=>({...x,p:byUrl.get(x.url)}));$('#cartitems').innerHTML=items.map(({p,quantity,url})=>`<div class="cart-row"><img src="${esc(p.image)}" alt=""><div><h3>${esc(p.name)}</h3><small>${esc(p.sku)}</small><div><div class="quantity"><button data-qty="-1" data-url="${esc(url)}" aria-label="Decrease ${esc(p.name)} quantity">−</button><span>${quantity}</span><button data-qty="1" data-url="${esc(url)}" aria-label="Increase ${esc(p.name)} quantity">+</button></div><button class="remove" data-remove="${esc(url)}">Remove</button></div></div><strong>${cents(p)==null?'Quote needed':money(cents(p)*quantity)}</strong></div>`).join('')||'<p class="empty">Your next favorite belongs here.<br>Explore the collection to get started.</p>';
    const unknown=items.some(x=>cents(x.p)==null),subtotal=items.reduce((s,x)=>s+(cents(x.p)||0)*x.quantity,0),discount=card?.rewardAvailable?Math.round(subtotal*.25):0;
    $('#cart-totals').innerHTML=items.length?`<div class="total-row"><span>Merchandise</span><span>${unknown?'Quote needed':money(subtotal)}</span></div>${discount?`<div class="total-row discount"><span>Your five-order reward · 25%</span><span>−${money(discount)}</span></div>`:''}<div class="total-row"><span>Delivery</span><span>${config?.shippingCents!=null?money(config.shippingCents):'Calculated after delivery is configured'}</span></div><div class="total-row grand"><span>Merchandise after rewards</span><span>${unknown?'Quote needed':money(subtotal-discount)}</span></div><p class="checkout-note">Delivery and applicable taxes are additional.</p>`:'';
    $('#cart-reward').textContent=card?.rewardAvailable?'Your next merchandise order gets 25% off. No dollar cap.':`${card?.punches||0}/5 punches · Five paid orders earn 25% off the next.`;
    $('#checkout').disabled=!items.length||unknown;
    $('#cancel-checkout').hidden=!card?.pendingOrder;
  }
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.add)add(b.dataset.add);if(b.dataset.remove){bag=bag.filter(x=>x.url!==b.dataset.remove);bagChanged();}if(b.dataset.qty){const x=bag.find(x=>x.url===b.dataset.url);if(x){x.quantity+=Number(b.dataset.qty);bag=bag.filter(x=>x.quantity>0);bagChanged();}}if(b.dataset.category){$('#category').value=b.dataset.category;page=1;render();$('#shop').scrollIntoView();}});
  for(const id of ['search','category','sort'])$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=1;render();});
  $('#prev').onclick=()=>{page--;render();$('#shop').scrollIntoView();};$('#next').onclick=()=>{page++;render();$('#shop').scrollIntoView();};
  $('#bag').onclick=()=>{renderCart();$('#cart').showModal();};
  $('#open-card').onclick=async()=>{try{await ensureCard();toast('Your punch card is ready. Save your card code.');}catch(e){$('#reward-status').textContent=e.message;}};
  $('#restore-card').onclick=()=>$('#restore').showModal();
  $('#copy-card').onclick=async()=>{try{await navigator.clipboard.writeText(card.id);toast('Card code copied. Keep it somewhere safe.');}catch{toast('Select and copy the card code shown on your card.');}};
  $('#restore-form').onsubmit=async e=>{e.preventDefault();const code=new FormData(e.target).get('code').trim();try{const restored=await request('/api/card',{code});card=restored;cardCode=code;save('chance2.card',code);renderCard();$('#restore').close();toast('Welcome back. Your punch card is restored.');}catch(e){$('#restore-status').textContent=e.message;}};
  $('#checkout').onclick=async()=>{const button=$('#checkout');button.disabled=true;$('#checkout-status').textContent='Opening your secure checkout…';try{await ensureCard();const session=await request('/api/checkout',{method:'POST',body:{items:bag}});if(session.state==='processing')throw Error('Your payment is still processing. Your punch will appear after confirmation.');const target=new URL(session.url);if(target.protocol!=='https:'||target.hostname!=='checkout.stripe.com')throw Error('Unexpected payment destination.');window.location.assign(session.url);}catch(e){$('#checkout-status').textContent=e.message;button.disabled=!bag.length;}};
  $('#cancel-checkout').onclick=async()=>{try{card=await request('/api/checkout/cancel',{method:'POST'});renderCard();$('#checkout-status').textContent='Pending checkout cancelled. Your punches are unchanged.';}catch(e){$('#checkout-status').textContent=e.message;}};
  const tileCategories=['Chairs & seating','Desks','Tables','Storage & shelving'];
  $('#category-tiles').innerHTML=tileCategories.map(c=>{const p=catalog.find(p=>category(p)===c);return `<button class="category-tile" data-category="${esc(c)}">${p?`<img src="${esc(p.image)}" alt="" loading="lazy">`:''}<span>${esc(c)} <b aria-hidden="true">↗</b></span></button>`;}).join('');
  $('#year').textContent=new Date().getFullYear();render();bagChanged();renderCard();
  request('/api/config').then(c=>{config=c;renderCart();}).catch(()=>{});
  if(cardCode)ensureCard().catch(()=>{$('#reward-status').textContent='Your saved card will reconnect when the shop connection is available.';});
  const query=new URLSearchParams(location.search);
  if(query.has('order')&&cardCode){(async()=>{try{await ensureCard();const result=await request('/api/orders/'+encodeURIComponent(query.get('order')));card=result.card;renderCard();$('#cart').showModal();if(result.state==='paid'){bag=[];bagChanged();$('#checkout-status').textContent='Thank you. Your payment is confirmed and your punch card is up to date.';}else $('#checkout-status').textContent=query.get('payment')==='cancelled'?'You returned without completing checkout. Your punches are unchanged. Use “Cancel pending checkout” to edit your bag.':'Your payment is awaiting confirmation. Your card will update after Stripe confirms payment.';}catch(e){toast(e.message);}})();}
})();
